def get_V():
    S0 = set()
    for a in range(20):
        for b in range(11):
            S0.add(11 * a + 20 * b)

    V = []
    for n in range(200):
        if n not in S0:
            V.append(n)
    return V

V = get_V()
print(f"V: {V}")
print(f"Size of V: {len(V)}")

adj = {n: [] for n in V}
for n in V:
    if n + 11 in V:
        adj[n].append(n + 11)
    if n + 20 in V:
        adj[n].append(n + 20)

print(f"Adj: {adj}")

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

print(fib(30))
